('bmlt-anatomyphys1-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"The renal corpuscle consists of:","translation":"","options":["Loop of Henle and collecting duct","Glomerulus and Bowman''s capsule","Proximal and distal tubules","Ureter and pelvis"],"correctIndex":1,"explanation":"The renal corpuscle is formed by the glomerulus enclosed by Bowman''s capsule.","explanationNe":"रेनल कर्पसकल ग्लोमेरुलस र त्यसलाई घेर्ने बोम्यान्स क्याप्सुलबाट बनेको हुन्छ।","topic":"Urinary system"}'::jsonb,true),
('bmlt-anatomyphys1-mock-026','BMLT','BMLT NHPC Licensing','mock','free',26,'{"question":"Which structure carries urine from kidney to urinary bladder?","translation":"","options":["Urethra","Ureter","Renal artery","Collecting duct"],"correctIndex":1,"explanation":"Each ureter transports urine from a kidney to the bladder.","explanationNe":"युरेटरले मिर्गौलाबाट पिसाबथैलीसम्म पिसाब लैजान्छ।","topic":"Urinary system"}'::jsonb,true)
