-- BMLT NHPC preparation: Human Anatomy & Physiology Batch 1
-- 25 MCQ Practice + 25 Mock Test questions
begin;
on conflict (content_id) do nothing;
commit;

select content_type, count(*) as question_count
from public.learning_content
where faculty='BMLT'
  and subject='BMLT NHPC Licensing'
  and content_data->>'topic' in ('Cardiovascular system','Respiratory system','Blood physiology','Digestive system','Endocrine system','Nervous system','Musculoskeletal system','Urinary system')
group by content_type
order by content_type;
